 const number=authored.slice(0,index+1).filter(e=>e.grade===grade).length;
 const id=`jr-v2-g${grade}-${String(number).padStart(2,'0')}`;
 const passage=paragraphs.join('\n');
 let start=0;
 const segments=paragraphs.map((text,i)=>{
  const segment={id:`${id}-p${i+1}`,label:`${i+1}`,start,end:start+[...text].length,text};
  start=segment.end+1; return segment;
 });
